require_once __DIR__.'/includes/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/config/database.php';
if(is_logged_in())redirect('profile.php');$errors=[];$email='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Жарамды email мекенжайын енгізіңіз.';if($password==='')$errors[]='Құпиясөзді енгізіңіз.';if(!$errors){$stmt=$pdo->prepare('SELECT id,name,email,password FROM users WHERE email = :email LIMIT 1');$stmt->execute(['email'=>$email]);$user=$stmt->fetch();if(!$user||!password_verify($password,$user['password']))$errors[]='Email немесе құпиясөз қате.';else{session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$user['id'],'name'=>$user['name'],'email'=>$user['email']];redirect('profile.php');}}}
$pageTitle='Жүйеге кіру — Apple Store';require __DIR__.'/includes/header.php';
?><section class="auth-layout"><div class="auth-card"><p class="eyebrow">ҚОШ КЕЛДІҢІЗ</p><h1>Аккаунтыңызға<br>кіріңіз.</h1><p class="auth-subtitle">Жеке кабинетке өту үшін деректеріңізді енгізіңіз.</p><?php if(!empty($_SESSION['flash'])): ?><div class="alert alert-success" role="status"><?= e($_SESSION['flash']) ?></div><?php unset($_SESSION['flash']); endif; ?><?php if($errors): ?><div class="alert alert-error" role="alert"><?php foreach($errors as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div><?php endif; ?><form method="post" class="form-stack" novalidate><?= csrf_field() ?><label>Email<input type="email" name="email" value="<?= e($email) ?>" autocomplete="email" required></label><label>Құпиясөз<input type="password" name="password" autocomplete="current-password" required></label><button class="button button-dark button-full" type="submit">Кіру</button></form><p class="auth-foot">Аккаунтыңыз жоқ па? <a href="register.php">Тіркелу</a></p></div><aside class="auth-aside"><span></span><p>Жеке кеңістігіңіз<br>осы жерден басталады.</p></aside></section><?php require __DIR__.'/includes/footer.php'; ?>
